  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "MK-458, a phenol-containing N-alkyl morphinan-like CNS agent with high assay transfer, had absolute oral bioavailability of only 4.8% (range 3.5–5.8%) in patients, directly demonstrating that this scaffold class can undergo extensive first-pass elimination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Tetrabenazine, another lipophilic tertiary-amine CNS drug with a ketone and high transfer score, had mean systemic availability of only 0.049 (4.9%) after oral dosing, consistent with very low F due to first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ergotamine had absolute oral bioavailability below 1% in patients, showing that potent CNS alkaloids can be almost completely lost presystemically; the high transfer score supports a low-F phenotype for the query under an inducer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "UK-224,671 showed very low human oral bioavailability (5–10%) attributed to poor absorption and P-gp efflux; rifampin co-treatment is known to induce such efflux and clearance pathways, reinforcing a low-F expectation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Danazol in the fasted state had absolute bioavailability of only 13%, showing that a high-transfer molecule can fall below the 20% threshold under ordinary oral dosing conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Danazol in a fed emulsion formulation reached 67% absolute bioavailability in humans, demonstrating that formulation and food can raise F; however, this condition-specific high value is not applicable to rifampin co-treatment and is outweighed by the consistent low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a hydromorphone-like morphinan with a phenolic OH and tertiary amine, and the prediction is made under rifampin co-treatment. High-transfer experimental analogues with similar CNS-drug features consistently show oral bioavailability well below 20%, and rifampin induction of first-pass metabolism and efflux would be expected to lower F further. No direct rifampin-hydromorphone record is available, so confidence is moderate.",
  "evidence_gaps": [
    "No direct experimental record for hydromorphone itself or for the query under rifampin co-treatment.",
    "No evidence molecule explicitly tests rifampin co-treatment; the interaction is inferred from rifampin's known induction of metabolic and efflux pathways.",
    "Danazol high-F records are formulation/fed-state dependent and do not inform the rifampin condition."
  ],
